<span style="font-size:11px;color:#888;margin-left:auto;">QUOTIDIEN &nbsp;|&nbsp; 17 JUILL. AU 17 AOÛ 2026</span>
</div>
<div style="padding:12px 14px 8px;">
<script>
(function(){
  var _cs = document.currentScript;
  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");

  function el(tag, attrs, txt){
    var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (txt !== undefined) e.textContent = txt;
    return e;
  }

  var margin = {left:62, top:18, right:24, bottom:46};
  var PW = 594, PH = 300 - margin.top - margin.bottom;

  var dates = ["17 juill.","20 juill.","21 juill.","22 juill.","23 juill.","24 juill.","27 juill.","28 juill.","29 juill.","30 juill.","31 juill.","3 août","4 août","5 août","6 août","7 août","10 août","11 août","12 août","13 août","14 août","16 août","17 août"];
  var data = [88.10,87.14,88.52,90.18,94.26,91.68,88.36,84.09,90.74,89.03,90.12,83.77,79.36,79.45,82.49,83.55,87.72,88.91,88.98,87.07,88.52,88.69,89.18];
  var n = data.length;

  var dMin = Math.min.apply(null, data);
  var dMax = Math.max.apply(null, data);
  var pad = (dMax - dMin) * 0.14;
  var yMin = dMin - pad, yMax = dMax + pad;

  function xp(i){ return margin.left + (i/(n-1)) * PW; }
  function yp(v){ return margin.top + PH - ((v - yMin)/(yMax - yMin)) * PH; }

  var gridSteps = 4;
  for (var g=0; g<=gridSteps; g++){
    var gy = margin.top + (g/gridSteps) * PH;
    svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:gy,y2:gy,stroke:"#ececec","stroke-width":0.5}));
  }

  var refVal = 85;
  var refY = yp(refVal);
  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:refY,y2:refY,stroke:"#2e7d32","stroke-dasharray":"3,3"}));

  var pathD = "M" + xp(0) + "," + yp(data[0]);
  for (var i=1;i<n;i++){ pathD += " L" + xp(i) + "," + yp(data[i]); }
  svg.appendChild(el("path",{d:pathD, fill:"none", stroke:"#4a5568", "stroke-width":"1.75"}));

  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));

  var lowIdx = 12;
  var lowX = xp(lowIdx);
  svg.appendChild(el("line",{x1:lowX,x2:lowX,y1:margin.top,y2:margin.top+PH,stroke:"#1a3560","stroke-opacity":"0.5","stroke-dasharray":"2,3"}));

  var lastX = xp(n-1), lastY = yp(data[n-1]);
  svg.appendChild(el("circle",{cx:lastX, cy:lastY, r:"4", fill:"#4a5568"}));

  var pillText = data[n-1].toFixed(2).replace(".", ",") + "\u00a0$";
  var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
  var pillH = 16;
  var pillX = lastX - pillW - 6;
  var pillY = lastY - pillH/2;
  if (pillX < margin.left) pillX = margin.left;
  svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:"3",fill:"#e8a825"}));
  svg.appendChild(el("text",{x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":"9","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#111111"}, pillText));

  for (var xi=0; xi<n; xi+=4){
    svg.appendChild(el("text",{x:xp(xi), y:margin.top+PH+16, "text-anchor":"middle", "font-size":"8", "font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif", fill:"#999"}, dates[xi]));
  }
  svg.appendChild(el("text",{x:xp(n-1), y:margin.top+PH+16, "text-anchor":"end", "font-size":"8", "font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif", fill:"#999"}, dates[n-1]));

  for (var yi=0; yi<=gridSteps; yi++){
    var yv = yMin + (yi/gridSteps) * (yMax-yMin);
    var yy = margin.top + PH - (yi/gridSteps) * PH;
    svg.appendChild(el("text",{x:margin.left-6, y:yy+3, "text-anchor":"end", "font-size":"8.5", "font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif", fill:"#aaa"}, Math.round(yv) + "\u00a0$"));
  }

  var curVal = data[n-1];
  if (Math.abs(refVal - curVal)/curVal >= 0.03){
    svg.appendChild(el("text",{x:margin.left+10,y:refY-10,"text-anchor":"start","font-size":"7","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif",fill:"#2e7d32","font-weight":"700"}, "T3 EIA PR\u00c9V. : 85\u00a0$"));
  }

  svg.appendChild(el("text",{x:lowX+6, y:margin.top+16, "text-anchor":"start", "font-size":"7", "font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif", fill:"#1a3560", "font-weight":"700"}, "CREUX DU 4 AO\u00db"));
  svg.appendChild(el("text",{x:margin.left+10, y:margin.top+PH-8, "text-anchor":"start", "font-size":"8", "font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif", fill:"#444"}, "P\u00c9AGE ET CESSEZ-LE-FEU EXPIRENT AUJOURD’HUI"));

  _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: Investing.com, données de clôture quotidienne des contrats à terme sur le Brent, du 17 juill. au 17 août 2026. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Le Brent s’est négocié entre 79,36&nbsp;$ et 94,26&nbsp;$ au cours du dernier mois sans rupture durable dans un sens ou l’autre, ce qui concorde avec la propre prévision de l’EIA d’une perturbation continue mais bornée jusqu’au troisième trimestre.</p>
<h2>Scénario de base et risque extrême</h2>
<p>Le scénario de base est la continuité, non l’escalade. L’Energy Information Administration américaine prévoit un Brent moyen d’environ 85&nbsp;$ le baril au troisième trimestre de 2026 et s’attend à ce que la majeure partie de la production du Moyen-Orient ne revienne vers des niveaux d’avant-conflit qu’au début de 2027, avec une perturbation d’environ 0,6 million de barils par jour qui persiste jusqu’à la fin de cette année-là, peu importe la façon dont les échéances d’aujourd’hui se résolvent. Cette prévision suppose déjà un détroit non résolu, ce qui est exactement ce que produit la journée d’aujourd’hui.</p>
<p>Le risque extrême est un élargissement du conflit au-delà de la guerre des pétroliers qui a défini jusqu’ici son empreinte économique. Les frappes de fin de semaine d’Israël au Liban ont tué un commandant supérieur du Hezbollah, ouvrant un front distinct de la confrontation directe avec l’Iran qui a jusqu’ici mené les prix du pétrole, et Washington prépare de nouvelles sanctions économiques visant à forcer la capitulation de l’Iran. Aucun de ces deux développements, à lui seul, ne ferait sortir le pétrole de la fourchette dans laquelle le marché a évolué cet été. Le fait que les deux surviennent la même semaine que l’expiration du cessez-le-feu et de la dispense de péages constitue la combinaison que le bureau signale comme un changement réel, et non incrémental, de probabilité.</p>
<h2>Ce que cela signifie pour les portefeuilles canadiens</h2>
<p>Le scénario de base appuie la réévaluation déjà visible dans les titres canadiens d’énergie et de matériaux et dans le rôle continu de l’or comme couverture, sans qu’une nouvelle manchette soit nécessaire pour le soutenir, puisque les propres chiffres de l’EIA supposent déjà que la perturbation se poursuit jusqu’en 2027. Le risque extrême est le scénario qui ferait sortir les portefeuilles canadiens de cette fourchette déjà intégrée, et il ne s’agit pas tant d’une information nouvelle que d’un ensemble de possibilités connues qui, jusqu’à aujourd’hui, n’étaient pas survenues au même moment que l’expiration du seul cadre qui avait structuré les attentes depuis juin.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients détenant des positions en énergie et en or canadiens se sentent probablement confortés par des mois de prix élevés soutenus, mais plusieurs ne peuvent distinguer l’expiration précise d’aujourd’hui de la tension générale au Moyen-Orient qu’ils ont absorbée pendant des mois sans grande conséquence sur leur portefeuille. Les clients diversifiés ressentent un malaise plus vague à l’égard de la région sans avoir une idée claire de ce qui a réellement changé aujourd’hui.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Deux choses expirent aujourd’hui dans le détroit d’Ormuz&nbsp;: le cessez-le-feu provisoire et la dispense de péages qui l’accompagnait. Aucune des deux expirations n’est une résolution, ni un effondrement. L’autorité iranienne sanctionnée ne peut toujours pas être payée légalement par la plupart des transporteurs, de sorte que le pétrole continue de circuler comme il le fait depuis des semaines, par des contournements plutôt que par une réouverture formelle. Le scénario qui ferait réellement sortir votre portefeuille de la fourchette où il a évolué tout l’été est une combinaison&nbsp;: une campagne israélienne élargie et une poussée de sanctions américaines plus dure survenant dans la même fenêtre que l’expiration d’aujourd’hui. C’est possible, non certain, et c’est exactement pourquoi nous maintenons vos positions en énergie et en couverture calibrées comme elles le sont.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> clients concentrés dans des titres canadiens d’énergie et de matériaux qui profitent de la réévaluation du scénario de base à pétrole élevé sans rééquilibrage récent.</p>
<p><strong>Incidence variable&nbsp;:</strong> clients diversifiés à exposition modeste aux matières premières qui ressentent les manchettes plus que leur portefeuille.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> clients détenant de l’or précisément comme couverture contre le scénario de risque extrême décrit ici, plutôt que comme position générale en matières premières.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Examiner la concentration des positions dans le secteur canadien de l’énergie, étant donné la perturbation que l’EIA prévoit déjà persister jusqu’en 2027</div>
<div class="checklist-item">Confirmer que les allocations en or et en couverture sont calibrées pour le scénario de risque extrême, pas seulement le scénario de base</div>
<div class="checklist-item">Signaler toute décision client à court terme calée sur une résolution du conflit, puisque les expirations d’aujourd’hui n’en produisent pas</div>
<div class="checklist-item">Documenter les conversations avec les clients aujourd’hui, étant donné la nature élevée mais toujours bornée de la manchette</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Ce qui expire réellement aujourd’hui dans le détroit d’Ormuz<br><br>
Bonjour [Nom du client],<br><br>
Faisant suite à notre appel. Deux choses expirent aujourd’hui, le cessez-le-feu provisoire et sa dispense de péages, et aucune des deux n’est une résolution ou un effondrement. L’autorité iranienne des péages sanctionnée ne peut toujours pas être payée légalement, de sorte que le pétrole continue de circuler par les mêmes contournements depuis des semaines. Vos positions en énergie et en couverture demeurent calibrées pour le scénario de base, avec de la marge pour réagir si le risque extrême dont nous avons discuté se concrétise réellement.<br><br>
N’hésitez pas à communiquer avec moi pour toute question.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''''respond-email'''', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Investisseurs autonomes détenant de l’énergie canadienne sans cadre sur les sanctions&nbsp;:</strong> un investisseur autonome qui a participé à la remontée énergétique de cette année n’a probablement jamais compris pourquoi le mécanisme des péages du détroit d’Ormuz ne peut simplement rouvrir aujourd’hui, ce qui signifie qu’il n’a aucun cadre pour savoir ce qui changerait réellement l’opération.</p>
<p><strong>Investisseurs en retrait déconcertés par des manchettes contradictoires sur Ormuz&nbsp;:</strong> des mois de nouvelles contradictoires au Moyen-Orient ont laissé certains investisseurs incapables de distinguer une manchette incrémentale d’un changement réel de probabilité, exactement la distinction que ce dossier établit.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Deux échéances ont expiré aujourd’hui dans le détroit d’Ormuz, et aucune n’est la résolution ou l’effondrement que certaines manchettes laissent entendre. Je voulais vérifier comment votre exposition à l’énergie est positionnée pour le scénario qui ferait réellement bouger le marché à partir d’ici.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>Un investisseur autonome qui lit les manchettes d’aujourd’hui sur le détroit d’Ormuz n’a aucun moyen de distinguer une expiration qui ne change rien légalement, puisque l’autorité des péages sanctionnée ne peut toujours pas être payée, de la combinaison précise d’une campagne israélienne élargie et de nouvelles sanctions américaines qui ferait réellement sortir le pétrole de sa fourchette estivale. La valeur d’un conseiller consiste à tracer clairement cette ligne et à positionner un portefeuille pour le scénario de base tout en maintenant une couverture calibrée pour le risque extrême, plutôt que de réagir à la manchette du moment.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<p>Comment votre exposition à l’énergie canadienne est-elle actuellement calibrée par rapport à la fourchette où le pétrole a évolué le mois dernier&nbsp;?</p>
<p>Détenez-vous quelque chose précisément comme couverture contre un conflit élargi au Moyen-Orient, par opposition à une exposition générale aux matières premières&nbsp;?</p>
<p>Que faudrait-il pour que vous changiez votre position, et la nouvelle d’aujourd’hui répondrait-elle à ce critère&nbsp;?</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de prospection</div>
<div class="email-box" id="prospect-email">
